package io.github.jesterportfolio.hearth.survival.travel;
import java.util.*;import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
final class CombatTravelTest {
    final AtomicLong clock=new AtomicLong(100_000);final UUID a=UUID.randomUUID(),b=UUID.randomUUID(),other=UUID.randomUUID();
    @Test void actual_hits_tag_both_users_and_refresh_without_shortening(){var tags=new CombatTags(clock::get,false);tags.hit(a,b);assertEquals(130_000,tags.deadline(a));assertEquals(130_000,tags.deadline(b));clock.addAndGet(15_000);tags.hit(a,b);assertEquals(145_000,tags.deadline(a));clock.set(110_000);tags.hit(a,b);assertEquals(145_000,tags.deadline(b));}
    @Test void expiry_boundary_and_round_up_match_30_seconds(){var tags=new CombatTags(clock::get,false);tags.hit(a,null);assertEquals(30,tags.remainingSeconds(a));clock.addAndGet(29_999);assertTrue(tags.blocked(a));assertEquals(1,tags.remainingSeconds(a));clock.incrementAndGet();assertFalse(tags.blocked(a));assertEquals(0,tags.remainingSeconds(a));}
    @Test void save_acknowledgement_cannot_erase_a_new_hit(){var tags=new CombatTags(clock::get,false);tags.hit(a,b);var batch=tags.pending();clock.incrementAndGet();tags.hit(a,null);tags.acknowledge(batch);assertEquals(Map.of(a,130_001L),tags.pending());}
    @Test void persisted_deadline_survives_new_instance_and_older_restore(){var old=new CombatTags(clock::get,false);old.hit(a,b);var restored=new CombatTags(clock::get,false);restored.restore(old.pending());restored.restore(Map.of(a,100_001L));assertEquals(130_000,restored.deadline(a));assertTrue(restored.blocked(b));}
    @Test void startup_guard_covers_unflushed_crash_state_without_resetting_longer_saved_tag(){var tags=new CombatTags(clock::get,true);assertTrue(tags.blocked(other));tags.restore(Map.of(a,160_000L));clock.addAndGet(30_000);assertFalse(tags.blocked(other));assertTrue(tags.blocked(a));}
    @Test void expired_dirty_rows_remain_until_acknowledged(){var tags=new CombatTags(clock::get,false);tags.hit(a,null);clock.addAndGet(40_000);tags.prune();assertFalse(tags.pending().isEmpty());tags.acknowledge(tags.pending());tags.prune();assertEquals(0,tags.deadline(a));}
    @Test void recipient_must_accept_once_with_original_sessions(){var q=new TpaRequests(clock::get,60_000);var sa=new Object();var sb=new Object();var r=q.request(a,b,sa,sb);assertTrue(q.accept(a,sa,sb,true).isEmpty());assertTrue(q.accept(b,new Object(),sb,true).isEmpty());assertTrue(q.accept(b,sa,sb,false).isEmpty());var moving=q.accept(b,sa,sb,true).orElseThrow();assertTrue(q.current(moving));assertTrue(q.accept(b,sa,sb,true).isEmpty());q.complete(moving,false);assertFalse(q.current(moving));assertEquals(0,q.size());}
    @Test void concurrent_requests_do_not_replace_consent_or_occupy_an_actor_twice(){var q=new TpaRequests(clock::get,60_000);var sa=new Object();var sb=new Object();var original=q.request(a,b,sa,sb);assertThrows(IllegalStateException.class,()->q.request(other,b,new Object(),sb));assertThrows(IllegalStateException.class,()->q.request(b,a,sb,sa));assertEquals(original,q.incoming(b).orElseThrow());assertEquals(1,q.size());}
    @Test void only_participants_can_cancel_and_moving_requests_cannot_replay(){var q=new TpaRequests(clock::get,60_000);var sa=new Object();var sb=new Object();var r=q.request(a,b,sa,sb);assertFalse(q.cancel(other,r.id()));var m=q.accept(b,sa,sb,true).orElseThrow();assertFalse(q.cancel(a,m.id()));q.complete(m,true);assertFalse(q.current(m));assertThrows(IllegalStateException.class,()->q.request(a,b,sa,sb));q.invalidate(a);assertEquals(0,q.size());}
    @Test void logout_death_and_expiry_invalidate_pending_consent(){var q=new TpaRequests(clock::get,15_000);q.request(a,b,new Object(),new Object());clock.addAndGet(15_000);assertTrue(q.incoming(b).isEmpty());q.request(a,b,new Object(),new Object());q.invalidate(b);assertEquals(0,q.size());}
    @Test void expired_moving_request_fails_final_guard_without_reopening_consent(){var q=new TpaRequests(clock::get,15_000);var sa=new Object();var sb=new Object();q.request(a,b,sa,sb);var m=q.accept(b,sa,sb,true).orElseThrow();clock.addAndGet(15_000);assertFalse(q.current(m));assertTrue(q.incoming(b).isEmpty());q.complete(m,false);assertEquals(0,q.size());}
    @Test void stale_chat_button_cannot_accept_a_replacement_request(){var q=new TpaRequests(clock::get,15_000);var sa=new Object();var sb=new Object();var old=q.request(a,b,sa,sb);clock.addAndGet(15_000);var fresh=q.request(other,b,sa,sb);assertTrue(q.accept(b,old.id(),sa,sb,true).isEmpty());assertFalse(q.cancel(b,old.id()));assertEquals(fresh,q.incoming(b).orElseThrow());assertTrue(q.accept(b,fresh.id(),sa,sb,true).isPresent());}
}
